package com.kartyavya.report.controller; import com.kartyavya.contracts.ReportStatus; import com.kartyavya.report.dto.ReportDtos.*; import com.kartyavya.report.service.ReportService; import jakarta.validation.Valid; import org.springframework.data.domain.Page; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/admin/reports") public class AdminReportController{private final ReportService s;public AdminReportController(ReportService s){this.s=s;}@GetMapping Page<ReportResponse> all(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return s.all(page,size);}@GetMapping("/pending-department")List<ReportResponse> pendingDepartment(){return s.pending(ReportStatus.PENDING_DEPARTMENT_SETUP);}@GetMapping("/pending-officer")List<ReportResponse> pendingOfficer(){return s.pending(ReportStatus.PENDING_OFFICER_ASSIGNMENT);}@PatchMapping("/{id}/assignment")ReportResponse assign(@PathVariable Long id,@Valid @RequestBody AssignmentRequest r,Authentication a,@RequestHeader(value="X-Correlation-Id",required=false)String c){return s.assign(id,r,a,c);}@PostMapping("/{id}/reprocess-routing")ReportResponse reprocess(@PathVariable Long id,Authentication a,@RequestHeader(value="X-Correlation-Id",required=false)String c){return s.reprocess(id,a,c);}}
